  tw_service_anyone: { en: 'Anyone with the link can use it.', 'zh-Hans': '任何拥有链接的人都可以使用。', 'zh-Hant': '任何擁有連結的人都可以使用。', ja: 'リンクを知っている人なら誰でも利用できます。', ko: '링크가 있는 사람은 누구나 사용할 수 있습니다.' },
