  tw_service_error_model: { en: 'This Bot’s model is not set up on this computer.', 'zh-Hans': '此电脑上尚未配置该 Bot 的模型。', 'zh-Hant': '此電腦上尚未設定該 Bot 的模型。', ja: 'このパソコンでは、この Bot のモデルが設定されていません。', ko: '이 컴퓨터에는 이 Bot의 모델이 설정되어 있지 않습니다.' },
