  tw_service_friends: { en: 'Only friends I choose', 'zh-Hans': '仅我选择的好友', 'zh-Hant': '僅限我選擇的好友', ja: '私が選んだ友だちだけ', ko: '내가 선택한 친구만' },
  tw_service_link: { en: 'Anyone with the link', 'zh-Hans': '任何拥有链接的人', 'zh-Hant': '任何擁有連結的人', ja: 'リンクを知っている人なら誰でも', ko: '링크가 있는 사람은 누구나' },
  tw_service_no_files: { en: 'Bots that need files bound to them cannot be offered as a service yet.', 'zh-Hans': '需要绑定文件的 Bot 暂不能作为服务提供。', 'zh-Hant': '需要綁定檔案的 Bot 暫時無法作為服務提供。', ja: 'ファイルの割り当てが必要な Bot は、まだサービスとして提供できません。', ko: '파일 연결이 필요한 Bot은 아직 서비스로 제공할 수 없습니다.' },
  tw_service_offer_title: { en: 'Offer a Bot outside your Teams', 'zh-Hans': '在团队之外提供 Bot', 'zh-Hant': '在團隊之外提供 Bot', ja: 'チームの外で Bot を提供', ko: '팀 밖에서 Bot 제공' },
  tw_service_offered_by: { en: 'Offered by', 'zh-Hans': '提供者', 'zh-Hant': '提供者', ja: '提供者', ko: '제공자' },
